"use strict";

var _AdditionalFilterActions = require("../AdditionalFilterActions.utils");
describe('shouldShowDelete', function () {
  var selected = 'UmVwb3J0RmlsdGVyOjExZWFhOWMyZGMzZGFiMDA4NTA3MDIyMGEzYzAyNGQw';
  var filterOptions = [{
    displayInApp: false,
    hoverText: 'Report Filter: Orem Dive',
    label: 'Report 1',
    showIcon: true,
    value: 'UmVwb3J0RmlsdGVyOjExZWFhOWMyZGMzZGFiMDA4NTA3MDIyMGEzYzAyNGQw'
  }];
  it('should equal true if showIcon true', function () {
    expect((0, _AdditionalFilterActions.shouldShowDelete)(selected, filterOptions)).toEqual(true);
  });
  it('should equal false if showIcon false', function () {
    filterOptions[0].showIcon = false;
    expect((0, _AdditionalFilterActions.shouldShowDelete)(selected, filterOptions)).toEqual(false);
  });
});